{
  "predictors": [
    {
      "name": "Employee Growth Rate",
      "construction": "Annual percentage change in total number of employees reported by the firm in its 10-K filings over the past year.",
      "rationale": "Rapid employee growth may indicate expansion and investment in future growth opportunities, leading to higher future returns.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "R&D to Revenue Ratio",
      "construction": "The ratio of research and development expenditure to total revenue, both sourced from the company's annual financial statements.",
      "rationale": "High R&D spending relative to revenue may signal innovation and future competitive advantages, potentially increasing future returns.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Dividend Growth Stability",
      "construction": "Standard deviation of annual percentage change in dividends paid over the past five years, using data from company financial statements.",
      "rationale": "Stocks with stable dividend growth may be perceived as financially robust, offering more predictable returns.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Insider Trading Volume",
      "construction": "The volume of insider purchases minus insider sales over the past year, gathered from insider trading reports.",
      "rationale": "Net insider buying may indicate confidence in the firm's future prospects, predicting higher returns.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Asset Turnover Trend",
      "construction": "Three-year trend in asset turnover ratio, calculated as revenue divided by total assets, using annual financial statements.",
      "rationale": "An improving asset turnover trend can indicate increasing operational efficiency, which may lead to higher future profitability and returns.",
      "higher_returns_for": "increasing values of the measure"
    },
    {
      "name": "International Revenue Exposure",
      "construction": "Percentage of total revenue derived from international operations, as reported in annual financial reports.",
      "rationale": "Firms with significant international revenues may benefit from global diversification and growth opportunities, enhancing future returns.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Cash Flow Consistency",
      "construction": "Standard deviation of operating cash flow over the past five years, using data from annual financial statements.",
      "rationale": "Consistent cash flow may indicate stable business operations, reducing risk and potentially increasing future returns.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Market Share Trend",
      "construction": "Three-year trend in market share, estimated from the company's revenue as a proportion of total industry revenue.",
      "rationale": "An increasing market share may suggest competitive strength and growth potential, leading to higher future returns.",
      "higher_returns_for": "increasing values of the measure"
    },
    {
      "name": "Deferred Revenue Ratio",
      "construction": "Ratio of deferred revenue to total revenue, both from the company's annual financial statements.",
      "rationale": "A higher deferred revenue ratio can indicate strong future sales commitments, potentially leading to higher future returns.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Patent Citation Impact",
      "construction": "Number of citations of the firm's patents in the past year, obtained from patent databases.",
      "rationale": "High citation counts may indicate valuable and influential technology, suggesting future growth and higher returns.",
      "higher_returns_for": "high values of the measure"
    }
  ]
}
